python3 -c '
from rest_api import RestAPI
import json

# Test 1: add user
api = RestAPI({"users": []})
res = api.post("/add", json.dumps({"user": "Adam"}))
assert json.loads(res) == {"name": "Adam", "owes": {}, "owed_by": {}, "balance": 0.0}, res
print("Test 1 passed")

# Test 2: both users have 0 balance
api = RestAPI({"users": [
    {"name": "Adam", "owes": {}, "owed_by": {}, "balance": 0.0},
    {"name": "Bob", "owes": {}, "owed_by": {}, "balance": 0.0}
]})
res = api.post("/iou", json.dumps({"lender": "Adam", "borrower": "Bob", "amount": 3.0}))
expected = {
    "users": [
        {"name": "Adam", "owes": {}, "owed_by": {"Bob": 3.0}, "balance": 3.0},
        {"name": "Bob", "owes": {"Adam": 3.0}, "owed_by": {}, "balance": -3.0}
    ]
}
assert json.loads(res) == expected, res
print("Test 2 passed")

# Test 3: borrower has negative balance
api = RestAPI({"users": [
    {"name": "Adam", "owes": {}, "owed_by": {}, "balance": 0.0},
    {"name": "Bob", "owes": {"Chuck": 3.0}, "owed_by": {}, "balance": -3.0},
    {"name": "Chuck", "owes": {}, "owed_by": {"Bob": 3.0}, "balance": 3.0}
]})
res = api.post("/iou", json.dumps({"lender": "Adam", "borrower": "Bob", "amount": 3.0}))
expected = {
    "users": [
        {"name": "Adam", "owes": {}, "owed_by": {"Bob": 3.0}, "balance": 3.0},
        {"name": "Bob", "owes": {"Adam": 3.0, "Chuck": 3.0}, "owed_by": {}, "balance": -6.0}
    ]
}
assert json.loads(res) == expected, res
print("Test 3 passed")

# Test 4: lender has negative balance
api = RestAPI({"users": [
    {"name": "Adam", "owes": {}, "owed_by": {}, "balance": 0.0},
    {"name": "Bob", "owes": {"Chuck": 3.0}, "owed_by": {}, "balance": -3.0},
    {"name": "Chuck", "owes": {}, "owed_by": {"Bob": 3.0}, "balance": 3.0}
]})
res = api.post("/iou", json.dumps({"lender": "Bob", "borrower": "Adam", "amount": 3.0}))
expected = {
    "users": [
        {"name": "Adam", "owes": {"Bob": 3.0}, "owed_by": {}, "balance": -3.0},
        {"name": "Bob", "owes": {"Chuck": 3.0}, "owed_by": {"Adam": 3.0}, "balance": 0.0}
    ]
}
assert json.loads(res) == expected, res
print("Test 4 passed")

# Test 5: lender owes borrower
api = RestAPI({"users": [
    {"name": "Adam", "owes": {"Bob": 3.0}, "owed_by": {}, "balance": -3.0},
    {"name": "Bob", "owes": {}, "owed_by": {"Adam": 3.0}, "balance": 3.0}
]})
res = api.post("/iou", json.dumps({"lender": "Adam", "borrower": "Bob", "amount": 2.0}))
expected = {
    "users": [
        {"name": "Adam", "owes": {"Bob": 1.0}, "owed_by": {}, "balance": -1.0},
        {"name": "Bob", "owes": {}, "owed_by": {"Adam": 1.0}, "balance": 1.0}
    ]
}
assert json.loads(res) == expected, res
print("Test 5 passed")

# Test 6: lender owes borrower less than new loan
api = RestAPI({"users": [
    {"name": "Adam", "owes": {"Bob": 3.0}, "owed_by": {}, "balance": -3.0},
    {"name": "Bob", "owes": {}, "owed_by": {"Adam": 3.0}, "balance": 3.0}
]})
res = api.post("/iou", json.dumps({"lender": "Adam", "borrower": "Bob", "amount": 4.0}))
expected = {
    "users": [
        {"name": "Adam", "owes": {}, "owed_by": {"Bob": 1.0}, "balance": 1.0},
        {"name": "Bob", "owes": {"Adam": 1.0}, "owed_by": {}, "balance": -1.0}
    ]
}
assert json.loads(res) == expected, res
print("Test 6 passed")

# Test 7: lender owes borrower same as new loan
api = RestAPI({"users": [
    {"name": "Adam", "owes": {"Bob": 3.0}, "owed_by": {}, "balance": -3.0},
    {"name": "Bob", "owes": {}, "owed_by": {"Adam": 3.0}, "balance": 3.0}
]})
res = api.post("/iou", json.dumps({"lender": "Adam", "borrower": "Bob", "amount": 3.0}))
expected = {
    "users": [
        {"name": "Adam", "owes": {}, "owed_by": {}, "balance": 0.0},
        {"name": "Bob", "owes": {}, "owed_by": {}, "balance": 0.0}
    ]
}
assert json.loads(res) == expected, res
print("Test 7 passed")

# Test 8: get users with payload
api = RestAPI({"users": [
    {"name": "Adam", "owes": {}, "owed_by": {}, "balance": 0.0},
    {"name": "Bob", "owes": {}, "owed_by": {}, "balance": 0.0}
]})
res = api.get("/users", json.dumps({"users": ["Bob"]}))
expected = {
    "users": [
        {"name": "Bob", "owes": {}, "owed_by": {}, "balance": 0.0}
    ]
}
assert json.loads(res) == expected, res
print("Test 8 passed")

# Test 9: get all users
res = api.get("/users")
expected = {
    "users": [
        {"name": "Adam", "owes": {}, "owed_by": {}, "balance": 0.0},
        {"name": "Bob", "owes": {}, "owed_by": {}, "balance": 0.0}
    ]
}
assert json.loads(res) == expected, res
print("Test 9 passed")
'

